		void Colorized_Effect(EffectContext& ctx)
		{
			using namespace ff;
			const vec4 COLOR = LoadColor(ctx.Color());
			vec3 gain = 1.5f * (1.0f + (COLOR.xyz() - 0.5f) * 4.0f);
			float alpha = 1.0f + (COLOR.w - 0.5f) * 4.0f;
			int passes = clamp(int(ceil(max(0.0f, max(max(gain.x, gain.y), gain.z)))), 1, 3);
			for (int i = 0; i < passes; i++) {
				FixedFunctionPass p;
				Store(p.Color, vec4(gain - float(i), alpha));
				if (i > 0) {
					p.Blend = FixedFunctionPass::BlendMode::Additive;
				}
				ctx.SubmitQuad(p);
			}
		}

