		// FrozenMask - from FrozenMask.shader:fixed_function(pvr, pica, gu, gs, rdp, legacygl)
		// Shared by: FrozenMask, FrozenMask (USE_PALETTE), BatchedFrozenMask, BatchedFrozenMask (USE_PALETTE)
		void FrozenMask_Effect(EffectContext& ctx)
		{
			using namespace ff;
			const vec4 COLOR = LoadColor(ctx.Color());
			float t = clamp(COLOR.w, 0.0f, 1.0f);
			FixedFunctionPass sprite;
			ctx.SubmitQuad(sprite);
			if (t > 0.0f) {
				FixedFunctionPass ice;
				Store(ice.Color, vec4(0.0f, 0.0f, 0.0f, 0.8f * t));
				Store(ice.OffsetColor, vec3(0.1f, 0.51f, 0.7f));
				ice.HasOffsetColor = true;
				ctx.SubmitQuad(ice);
			}
		}

		// Outline - from Outline.shader:fixed_function()
		// Shared by: Outline, BatchedOutline, OutlinePalette [OutlinePalette.shader:fixed_function()], BatchedOutlinePalette [OutlinePalette.shader:fixed_function()]
		void Outline_Effect(EffectContext& ctx)
		{
			using namespace ff;
			const vec4 COLOR = LoadColor(ctx.Color());
			if (COLOR.w > 0.0f && ctx.HasTexelStep()) {
				vec2 step = vec2(ctx.TexelStepX(), ctx.TexelStepY());
				for (int oy = -1; oy <= 1; oy++) {
					for (int ox = -1; ox <= 1; ox++) {
						if (ox != 0 || oy != 0) {
							FixedFunctionPass p;
							Store(p.Color, vec4(0.0f, 0.0f, 0.0f, COLOR.w));
							Store(p.OffsetColor, vec3(COLOR.z));
							p.HasOffsetColor = true;
							Store(p.ScreenOffset, step * vec2(float(ox), float(oy)));
							ctx.SubmitQuad(p);
						}
					}
				}
			}
			FixedFunctionPass sprite;
			ctx.SubmitQuad(sprite);
		}

